insert into public.registre(kind, id, data) values
('doc', 'bloc_mem_02_presentation_de_lappel_doffres', '{"kind": "bloc", "title": "PRESENTATION DE L’APPEL D’OFFRES", "html": "Objet : Réseau de Chaleur – Le Mans Nord – Coulaines\n\nNotre présent mémoire technique détaille notre organisation et nos méthodologies pour la réalisation du lot « POSE » du marché LE MANS 2025\n\nMAITRE D’OUVRAGE                                   MAITRE D’OUVRAGE DELEGUE\n\nLE MANS Métropole                                                               Engie Solutions\n\nMAITRE D’OEUVRE\n\nSUEZ\n\nENTREPRISE\n\nSoudure Construction Réseaux", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_03_presentation_de_notre_entreprise', '{"kind": "bloc", "title": "Présentation de notre entreprise", "html": "Soudure Construction Réseaux\n\nSiège social :\n\n12, Rue Emmanuel Philipot – 35230 Rennes\n\nCAPITAL : 50 000 euros\n\nN° TVA intracommunautaire : FR 74 815318712\n\nCode APE : 3311Z\n\nTéléphone : 09 75 24 14 73\n\nMail : mlebihan@scr-soudure.fr", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_04_presentation_de_notre_entreprise_notre_entreprise', '{"kind": "bloc", "title": "Présentation de notre entreprise › Notre entreprise", "html": "Implantée en Ile et Vilaine, à proximité immédiate de Rennes, notre entreprise est spécialisée dans la pose de réseaux de chaleur et de refroidissement.\n\nDepuis 2016, nous avons développé un savoir-faire spécifique reconnu par nos clients et partenaires.\n\nRenforcé aujourd’hui par 62 salariés expérimentés, les femmes et les hommes sont au cœur de notre réussite.\n\nNos collaborateurs sont tous impliqués dans notre démarche qualité par des réunions de sensibilisation, des formations et une responsabilisation dans leur quotidien.\n\nIls sont compétents et autonomes quant à la prise de décisions urgentes sur les chantiers, ce qui permet à nos équipes d’être très réactives et de respecter les délais et contraintes techniques rencontrés.\n\nLa proximité d’agences régionales, les qualifications et la disponibilité de nos équipes, seront pour vous les plus sûrs garants d’un service approprié.", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_05_analyse_du_chantier_et_de_ses_contraintes_preambule_techniqu', '{"kind": "bloc", "title": "Analyse du chantier et de ses contraintes › Préambule technique et commercial", "html": "Notre société ne pourra être tenue pour responsable des erreurs et omissions contenues dans les dossiers techniques remis par le Client.\n\nDans ces hypothèses, seule la responsabilité du Client pourra être engagée.\n\nToutefois notre société s’engage à faire connaitre au Client les erreurs qu’elle détecterait.\n\nTous changements de lois, réglementations, y compris ceux qui sont propres au Client, survenus après la remise de la présente offre et qui affectent notamment son exécution, sa durée, son prix, ses modalités d’exécution, ses spécifications et son objet, devront intégralement être pris en charge par le Client qui s’y oblige.\n\nÉgalement, notre société ne pourrait être tenue responsable des retards et surcouts éventuels, liés à des cas de force majeure (guerre, émeute, incendie, grève totale ou partielle, épidémies, …)", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_06_analyse_du_chantier_et_de_ses_contraintes_documents_de_refer', '{"kind": "bloc", "title": "Analyse du chantier et de ses contraintes › Documents de références", "html": "Notre proposition est basée sur les documents fournis à la consultation :\n\nDPGF V2\n\nCCTP - Réseau de chaleur Le Mans_IndA\n\n3.0_1_Annexe_CCTP_Sous-stations_v2\n\n3.3_Planning_RCU_LE_MANS_V3_25102024\n\nAdditif_consultation_RCU_LeMans_25_10_2024\n\nPlans DWG\n\nSTG Réseau preisolé - 08072024 - indice J.3", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_09_methodologie_de_realisation_des_travaux_description_de_la_pr', '{"kind": "bloc", "title": "Méthodologie de réalisation des travaux › Description de la prestation", "html": "Les prestations confiées à la société SCR dans le cadre de ce projet seront les suivantes :\n\nETUDES\n\nRéalisation des études et transmission des Livrables du projet, en particulier :\n\nFourniture de la liste des livrables adaptée au projet\n\nOrganigramme opérationnel, détaillé et nominatif\n\nListe des sous-traitants éventuels\n\nRédaction des dossiers d’épreuves\n\nRédaction des PV d’auto-contrôles\n\nDOE\n\nTRAVAUX DE CANALISATIONS :\n\nPréparation de chantier\n\nManutention des canalisations pré-isolés\n\nDéchargements\n\nBardages fond de fouilles\n\nTuyauterie et soudure (cf. modes opératoires)\n\nARC\n\nTIG\n\nTuyauterie et soudure pour fonçages (cf. Annexes Lot 1-2-3)\n\nContrôle radiographique des soudures (cf. modes opératoires)\n\n20% des soudures du feeder\n\n10% des soudures d’antennes\n\n100% des soudures sur secteurs spécifiques (fonçage, encorbellement, raccordements…)\n\nRéalisation des kits de jonction pré-isolés (cf. modes opératoires)\n\nTriple étanchéité\n\nPose d’ensembles de purges et de vidanges\n\nPurges par tés droits\n\nVidanges par gravité déportées\n\nPose de vannes\n\nPré-isolées\n\nPassage de pistons mousses\n\nPose de calorifugeage pour cheminement aérien sur façade (cf. Annexe lot 2)\n\nPose de supports / capotage pour cheminement en encorbellement (cf. Annexe lot 3)\n\nPRESTATIONS HYDRAULIQUES\n\nEpreuves hydrauliques finale (cf. modes opératoires)\n\n24h / 24 bars\n\nRinçage dynamique des réseaux\n\n2m/s\n\nPassivation\n\nRemplissage en eau adoucie\n\nFOURNITURES\n\nFourniture des ensembles de vannes en SST (cf. Annexes Lot 1-2-3)\n\nFourniture des vannes et accessoires pour point de purge\n\nFournitures des accessoires pour point de vidange\n\nFournitures de colliers de centrage pour les opérations de forage\n\nFourniture de calorifugeage pour cheminement aérien sur façade (cf. Annexe lot 2)\n\nFourniture de supports / capotage pour cheminement en encorbellement (cf. Annexe lot 3)\n\nHORS PRESTATIONS\n\nTous travaux de génie civil et terrassement\n\nTous travaux de pompage et rabattement de nappe\n\nAccès sécurisé fond de fouille\n\nBase vie\n\nManipulation, déplacement, modification de boisages, blindages, etc.\n\nTransfert, chargements, déchargements et déplacement de tubes, d’une zone de stockage distante aux fronts de chantiers.", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_10_regles_engagements_et_organisation_hse_sur_le_chantier_objec', '{"kind": "bloc", "title": "Règles, engagements et organisation HSE sur le chantier › Objectif & spécificités HSE du projet", "html": "Cette partie a pour objet de préciser les objectifs et mesures adoptées par l’entreprise SCR, concernant la réalisation de ses chantiers en adéquations avec les prescriptions d’Hygiène, de Santé, de Sécurité et d’Environnement (HSSE).\n\nCes objectifs et mesures répondent aux obligations de l’employeur figurants à l’article L4121-1 du Code du Travail :\n\n« L’employeur prend les mesures nécessaires pour assurer la sécurité et protéger la santé physique et mentale des travailleurs.\n\nCes mesures comprennent :\n\nDes actions de prévention des risques professionnels\n\nDes actions d’information et de formation\n\nLa mise en place d’une organisation et de moyens adaptés.\n\nL’employeur veille à l’adaptation de ces mesures pour tenir compte du changement des circonstances et tendre à l’amélioration des situations existantes ».\n\nCette partie constitue donc un outil pour répondre aux objectifs HSE de l’entreprise, déclinant ainsi les mesures figurant à l’article L4121-2 du Code du Travail fondées sur les principes généraux de prévention suivant :\n\nIdentifier les risques,\n\nEvaluer les risques qui ne peuvent être évités,\n\nCombattre les risques à la source,\n\nAdapter le travail à l’homme, en particulier, ce qui concerne la conception des postes de travail et de protection, en vue notamment de limiter le travail monotone et le travail cadencé et de réduire les effets de ceux-ci sur la santé,\n\nTenir compte de l’état d’évolution de la technique,\n\nRemplacer ce qui est dangereux par ce qui n’est pas dangereux ou par ce qui est moins dangereux,\n\nPlanifier la prévention en y intégrant dans un ensemble cohérent, la technique, l’organisation du travail, les conditions de travail, les relations sociales et l’influence des facteurs ambiants,\n\nPrendre des mesures de protection collective en leur donnant la priorité sur les mesures de protection individuelles,\n\nDonner les instructions appropriées aux travailleurs.\n\nIl est important de préciser que l’application de ces principes généraux de prévention s’impose à tous les intervenants sur le chantier (Personnel SCR, sous-traitants, locatiers…)\n\nLes prescriptions dans les domaines HSE résultent en grande partie des dispositions techniques et administratives prévues par la loi et les textes réglementaires.\n\nMais, elles dépendent aussi et surtout de l’implication du gérant et du personnel d’Encadrement et de Maîtrise (Personnel administratif, Chargé d’Affaires, Conducteur de travaux, Chef de chantier et Responsable QHSE) qui, au travers de la Politique HSE d’entreprise, doivent, chacun à leur niveau apporter les moyens Techniques, Humains et Organisationnels (THO) en leur possession, pour garantir :\n\nLe respect des engagements QHSE de l’entreprise.\n\nLeur mise en application dans les phases de conceptions (bureau d’étude), et de réalisation (atelier & chantier).\n\nAssurer le retour d’expérience pour adopter une démarche perpétuelle d’amélioration continue.\n\nEn détail, les objectifs sont :\n\nD’assurer la conformité aux réglementations locales et nationales en matière d’Hygiène/Santé, Sécurité et Environnement.\n\nD’assurer la conformité avec les exigences HSE du Client.\n\nDe mettre en place les processus de prévention permettant d’identifier et réduire en amont toutes difficultés et/ou incidents potentiels relatifs à l’Hygiène, la Santé, la Sécurité et l’Environnement pendant l’exécution des travaux de construction ou d’installation.\n\nD’assurer des actions correctives efficaces pour pallier toutes difficultés et/ou incidents relatifs à l’Hygiène, la Santé, la Sécurité et l’Environnement pendant l’exécution des travaux de construction ou d’installation et que les thèmes HSE soient pris en compte à chaque étape du processus de décision.\n\nD’assurer la cohérence entre le système de gestion HSE de l’entreprise et les attentes HSE du Client.\n\nD’établir une compréhension commune des exigences HSE spécifiques et de s’assurer que toutes les personnes travaillant sur le chantier soient sensibilisées à ces exigences et auront reçues le cas échéant les formations adéquates.\n\nDe façon concrète, durant les travaux de construction et le démarrage des installations, l’entreprise SCR, cherche à atteindre les résultats suivants :\n\nZéro accident.\n\nUn chantier calme et serein.\n\nUn travail d’équipe et un partenariat continu.\n\nDes travaux de qualité.\n\nRespecter la propreté des lieux : zone entreprise, chantier et environs.\n\nPour atteindre ces objectifs, l’entreprise attache une importance particulière aux points suivants :\n\nPréparation minutieuse des travaux incluant les prescriptions HSE d’entreprise.\n\nAnalyse préalable des risques générés par l’entreprise ainsi que ceux générés par la sous-traitance.\n\nRespect des règles d’hygiène de sécurité et d’environnement.\n\nSystème de management efficace.\n\nFormation et sensibilisation du personnel.\n\nComportement de chacun.", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_11_regles_engagements_et_organisation_hse_sur_le_chantier_moyen', '{"kind": "bloc", "title": "Règles, engagements et organisation HSE sur le chantier › Moyen humains & missions associés", "html": "Le Conducteur de travaux, M. PERRINEL Nicolas, assurera une présence ponctuelle selon les exigences de son client quant au suivi des prescriptions HSE sur ce chantier. Il est chargé notamment :\n\nDe la prévention et de la sensibilisation du personnel via l’accueil sécurité et ¼ d’heure sécurité.\n\nDe l’analyse des risques importés et exportés,\n\nDe la préparation aux situations d’urgence,\n\nDe la gestion et de l’analyse des incidents/accidents survenant sur le chantier,\n\nDe la mise en place des actions curatives, correctives et préventives tout au long du chantier,\n\nDu reporting hebdomadaire HSE,\n\nD’assurer le retour d’expérience ainsi que l’amélioration continue de la Politique HSE d’entreprise,\n\nD’assurer le suivi Qualité d’un point de vue documentaire et livrable au Client", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_12_regles_engagements_et_organisation_hse_sur_le_chantier_moyen', '{"kind": "bloc", "title": "Règles, engagements et organisation HSE sur le chantier › Moyens techniques & organisationnels liés à la sécurité", "html": "STATIONNEMENT DES VÉHICULES\n\nUne aire de stationnement VL est prévue à la base vie.\n\nLe stationnement des VL s’effectue en arrière, prêt à partir.\n\nSAUVETEURS SECOURISTES DU TRAVAIL\n\nDes Sauveteurs Secouristes du Travail seront présents en nombre suffisant (10% de l’effectif global, soit 1 personne par équipe à minima) sur le chantier.\n\nLes SST seront indentifiables par le logo règlementaire apposé sur le casque ou vêtement de travail.\n\nUne liste des SST du chantier sera communiquée au Client.\n\nChaque véhicule est équipé d’une trousse de 1er secours BTP (rouge).\n\nMOYENS DE COMMUNICATION & RÉPONSES AUX SITUATIONS D’URGENCE\n\nL’équipe SCR sera dotée sur le terrain d’un téléphone portable ainsi que d’un annuaire de chantier.\n\nUne feuille « En cas d’accident » sera diffusée et connue de tous.\n\nCONSIGNES À METTRE EN ŒUVRE EN CAS D’ACCIDENT / INCIDENT\n\nACCIDENT BENIN - CONSIGNES\n1 | Les gestes de 1er secours seront prodigués à la victime par le personnel SST (Sauveteur Secouriste du Travail) présents sur le chantier à l''aide du matériel de premiers secours.\n2 | Le conducteur de travaux SCR sera prévenu dans les plus brefs délais (CF annuaire)\n4 | La victime et/ou le secouriste décide en fonction de la blessure de la suite à donner.\n5 | L’accident bénin sera répertorié par le Responsable QHSE dans un registre prévu à cet effet\n\nACCIDENT GRAVE - CONSIGNES\n1 | Les soins et/ou gestes de secours seront prodigués à la victime par le personnel SST (Sauveteur Secouriste du Travail) présents sur le chantier à l''aide du matériel de premiers secours.\n2 | Le SST déclenche l’intervention des secours extérieurs adaptés (18 – 112) – Il donne le PR le plus proche.\n3 | Le SST envoi une personne au PR mentionné afin de réceptionner les secours dépêchés.\n4 | Le conducteur de travaux SCR sera prévenu dans les plus brefs délais (CF annuaire)\n6 | La victime est prise en charge par les secours extérieurs – le SST se tient à disposition des secours\n7 | L’accident grave sera répertorié par le Responsable QHSE SCR dans un registre prévu à cet effet\n8 | Une analyse d’accident ainsi qu’un rapport sera établi par le Responsable QHSE SCR.\n9 | Le Client, la CARSAT, l’Inspection du Travail et l’OPPBTP seront tenus informé de ces faits.\n\nACCIDENT MORTEL - CONSIGNES\n1 | Les gestes de 1er secours seront prodigués à la victime par le personnel SST (Sauveteur Secouriste du Travail) présents sur le chantier à l''aide du matériel de premiers secours.\n2 | Le SST déclenche l’intervention des secours extérieurs adaptés (18 – 112) – Il donne le PR le plus proche.\n3 | Le SST envoi une personne au PR mentionné afin de réceptionner les secours dépêchés.\n4 | Le SST préserve les lieux en sécurisant la zone (pour les besoins de l’enquête) et regroupe le plus de témoins possibles\n5 | Le conducteur de travaux SCR sera prévenu dans les plus brefs délais (CF annuaire)\n7 | Le Client, la CARSAT, l’Inspection du Travail et l’OPPBTP, la gendarmerie seront tenus informé de ces faits.\n\nLe point de rassemblement se situe à la BASE VIE.\n\nACCUEIL SÉCURITÉ DE CHANTIER\n\nLes salariés SCR (CDI / CDD / intérimaires), se verront dispenser un « accueil sécurité » de chantier dès leur arrivée sur site, par le chef de chantier ou le cas échéant le Responsable QHSE d’entreprise.\n\nLe contenu de cette formation sera le suivant : (15 à 30 minutes)\n\nPrésentation du chantier et de l’organigramme.\n\nPrésentation de l’organisation logistique, la gestion des secours.\n\nPrésentation des risques inhérents à leur activité et mesures préventives associées.\n\nL’accueil sécurité sera tracé et emmargé par l’accueillant et l’accueilli.\n\nLes papiers administratifs obligatoires seront remis pour donner suite à cet accueil (visite médicale, habilitations spécifiques…)\n\nFORMATION DU PERSONNEL\n\nL’entreprise SCR assure que le personnel présent sur chantier dispose des compétences, formations et habilitations requises pour effectuer les tâches qui lui sont confiées.\n\nCertificat d’Aptitude à la Conduite En Sécurité (CACES) & Autorisation de conduite\n\nL’entreprise SCR assure que tout le personnel opérant des grues mobiles, auxiliaires, engins de chantier à conducteurs portés, plates-formes élévatrices mobiles de personnes, chariot automoteur … sont titulaires de l’autorisation de conduite délivrée par les chefs d’établissement conformément à la règlementation en vigueur.\n\nUtilisation d’équipements spécifiques\n\nL’entreprise SCR assure que le personnel utilisant des équipements ou EPI spécifiques tels que harnais antichute, détecteurs CO2, oxygène/azote, est apte médicalement et a reçu les formations associées.\n\nHabilitations électriques\n\nL’entreprise SCR assure que le personnel amené à réaliser des travaux sous tension ou au voisinage de câbles ou canalisations électriques dispose d’une habilitation électrique adaptée (H0V / B0V).\n\nSauveteur Secouriste du Travail (SST)\n\nChaque secouriste doit être à jour de formation et de recyclage. Les SST doivent être clairement identifiés par apposition du logo règlementaire sur le casque ou vêtement de travail.\n\nInitiation lutte anti-pollution\n\nL’entreprise SCR assure que le personnel travaillant sur le site sait à minima localiser et se servir des moyens de lutte anti-pollution mis à sa disposition : Kits anti-pollution, absorbant…\n\nVisiteurs\n\nLes visiteurs occasionnels doivent impérativement passer l’accueil sécurité chantier.\n\nLes visiteurs doivent respecter les règles générales du chantier en matière de port d’EPI, de règles de circulation, etc… Il leur est interdit de travailler.\n\nEQUIPEMENTS DE SÉCURITÉ COLLECTIVE\n\nTrousse de secours\n\nL’entreprise SCR dote chacune de ses équipes d’une trousse de premiers secours présente à minima dans TOUS les véhicules de liaisons ainsi qu’en base vie.\n\nKits de dépollution\n\nL’entreprise SCR dote chacun de ses véhicules et engins de chantier d’un kit de dépollution.\n\nExtincteurs\n\nL’entreprise SCR dote chacun de ses véhicules de chantier d’un extincteur ABC 2kg en cabine, ainsi qu’un extincteur ABC 6kg sur le châssis (PL). Les engins de chantier sont dotés d’un extincteur ABC 2kg en cabine.\n\nCe matériel, propriété de l’entreprise doit être placé bien en évidence et rester toujours visible et accessible. Les caractéristiques et l’usage de ce matériel doivent être affichés et connus de tout le personnel.", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb),
('doc', 'bloc_mem_14_validite_de_loffre', '{"kind": "bloc", "title": "VALIDITE DE L’OFFRE", "html": "| Pour SCR | Pour le Client\nNom | LE BIHAN Ethan | \nFonction | Chargé d’Affaires | \nDate | 19/11/2024 | \nVisas | \n\nNotre offre est valable 4 mois à partir de sa date d’émission hors offre matériels valable 2 mois.", "src": "O2410-10 · mémoire technique (gagné)", "req": {"none": true}, "by": "import", "at": "2026-10-13T00:00:00Z"}'::jsonb)
